using System;using System.Data;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace AshkanHotelManager{public partial class GuestFolioForm:Form{ComboBox guests;DataGridView stays,folio;Label balance;public GuestFolioForm(){InitializeComponent();Text=App.T("guestFolio");BackColor=Ui.Bg;Build();App.ApplyDirection(this);}void Build(){var head=new Label{Text=App.T("guestFolio"),Dock=DockStyle.Top,Height=58,Font=Ui.Font(22,FontStyle.Bold),ForeColor=Ui.Text,Padding=new Padding(18)};Controls.Add(head);var bar=Ui.SurfacePanel();bar.Dock=DockStyle.Top;bar.Height=80;guests=new ComboBox{Width=260,DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(18,22)};foreach(DataRow r in DataStore.Db.Tables["Guests"].Rows)guests.Items.Add(Convert.ToString(r["FullName"]));guests.SelectedIndexChanged+=(s,e)=>RefreshData();var charge=Ui.Btn(App.T("charge"));charge.Width=130;charge.Location=new Point(300,20);charge.Click+=(s,e)=>AddEntry("Charge");var pay=Ui.Ghost(App.T("payment"));pay.Width=130;pay.Location=new Point(440,20);pay.Click+=(s,e)=>AddEntry("Payment");balance=new Label{Width=260,Height=40,Location=new Point(590,20),Font=Ui.Font(12,FontStyle.Bold),ForeColor=Ui.Text};bar.Controls.AddRange(new Control[]{guests,charge,pay,balance});Controls.Add(bar);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=260};stays=new DataGridView{Dock=DockStyle.Fill};folio=new DataGridView{Dock=DockStyle.Fill};Ui.Grid(stays);Ui.Grid(folio);split.Panel1.Controls.Add(stays);split.Panel2.Controls.Add(folio);Controls.Add(split);split.BringToFront();bar.BringToFront();head.BringToFront();if(guests.Items.Count>0)guests.SelectedIndex=0;}void AddEntry(string type){if(guests.SelectedItem==null)return;using(var d=new FolioEntryForm(type)){if(d.ShowDialog(this)!=DialogResult.OK)return;DataStore.Db.Tables["Folio"].Rows.Add(DataStore.Next("Folio"),guests.Text,"",d.Description,d.Amount.ToString(),type,DateTime.Now.ToString("yyyy-MM-dd HH:mm"));DataStore.Save();RefreshData();}}void RefreshData(){if(guests.SelectedItem==null)return;string g=guests.Text.Replace("'","''");stays.DataSource=new DataView(DataStore.Db.Tables["Reservations"],"Guest='"+g+"'","CheckIn DESC",DataViewRowState.CurrentRows);folio.DataSource=new DataView(DataStore.Db.Tables["Folio"],"Guest='"+g+"'","Date DESC",DataViewRowState.CurrentRows);decimal b=0;foreach(DataRow r in DataStore.Db.Tables["Folio"].Select("Guest='"+g+"'")){decimal a;if(decimal.TryParse(Convert.ToString(r["Amount"]),out a))b+=Convert.ToString(r["Type"])=="Payment"?-a:a;}balance.Text=App.T("balance")+": "+b.ToString("N0");balance.ForeColor=b>0?Ui.Danger:Ui.Green;}}
class FolioEntryForm:Form{public string Description{get;private set;}public decimal Amount{get;private set;}TextBox desc,amount;public FolioEntryForm(string type){Text=type;Width=430;Height=220;StartPosition=FormStartPosition.CenterParent;BackColor=Ui.Bg;desc=new TextBox{Left=25,Top=30,Width=360};amount=new TextBox{Left=25,Top=75,Width=360};var ok=Ui.Btn(App.T("save"));ok.Left=25;ok.Top=120;ok.Width=120;ok.Click+=(s,e)=>{decimal a;if(String.IsNullOrWhiteSpace(desc.Text)||!decimal.TryParse(amount.Text,out a)||a<=0)return;Description=desc.Text;Amount=a;DialogResult=DialogResult.OK;Close();};Controls.AddRange(new Control[]{desc,amount,ok});App.ApplyDirection(this);}}}